message.content:
{
"title": "Fee, Fly, Foe, Fund",
"language": "en",
"recommended_level": "6th-8th level",
"hook": "Two tendays ago, cloud giants attacked the town of Nightstone, slaying many of its inhabitants including Lady Velrosa Nandar, a Waterdhavian noble and High Steward of the town.",
"npcs": [
    {
        "name": "Regina",
        "role": "female halfling, housekeeper"
    },
    {
        "name": "Talurth Nandar",
        "role": "current patriarch of House Nandar"
    }
],
"locations": [
    "House Nandar's villa, North Ward, Waterdeep",
    "Nandar hunting lodge, Ardeep Forest"
],
"threats": [
    "Attacking cloud giants",
    "Possible future giant threats on the Sword Coast",
    "Doppelganger threat replacing the character of the player to the left"
],
"rewards": [
    "A symbol of House Nandar, embroidered crest",
    "100 gp for delivering the crest",
    "250 gp per giant slain with proof in the form of severed right ears",
    "Worthwhile future employment from the Lords’ Alliance",
    "Trust and friendship symbol from House Nandar"
]
}

